class Solution {
public:
    std::string largestGoodInteger(std::string num) {
        for (char c = '9'; c >= '0'; --c) {
            std::string triple(3, c);
            if (num.find(triple) != std::string::npos) {
                return triple;
            }
        }
        return "";
    }
};

class Solution {
    public String largestGoodInteger(String num) {
        for (char c = '9'; c >= '0'; c--) {
            String triple = "" + c + c + c;
            if (num.contains(triple)) {
                return triple;
            }
        }
        return "";
    }
}

var largestGoodInteger = function(num) {
    for (let d = 9; d >= 0; d--) {
        const triple = String(d).repeat(3);
        if (num.includes(triple)) {
            return triple;
        }
    }
    return "";
};
